import{_ as e,c as t,o,ah as A}from"./chunks/framework.BxT5r71R.js";const _=JSON.parse('{"title":"回顾BEFIRST与MAZZEL的新作发行","titleTemplate":"Management 2 本篇","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/Management2/PART2/11_回顾BEFIRST与MAZZEL的新作发行.md","filePath":"zh-cn/Management2/PART2/11_回顾BEFIRST与MAZZEL的新作发行.md"}'),n={name:"zh-cn/Management2/PART2/11_回顾BEFIRST与MAZZEL的新作发行.md"};function r(E,a,i,l,Z,B){return o(),t("div",null,[...a[0]||(a[0]=[A('<p>► 2023年5月</p><h2 id="回顾be-first与mazzel的新作发行" tabindex="-1">回顾BE:FIRST与MAZZEL的新作发行 <a class="header-anchor" href="#回顾be-first与mazzel的新作发行" aria-label="Permalink to &quot;回顾BE:FIRST与MAZZEL的新作发行&quot;">​</a></h2><p>#BEFIRST #MAZZEL #良好的氛围</p><h3 id="只要他们自己始终保持兴奋与期待-这种氛围自然就会在周围蔓延开来。我想-这样的氛围很能吸引人。" tabindex="-1">“只要他们自己始终保持兴奋与期待，这种氛围自然就会在周围蔓延开来。我想，这样的氛围很能吸引人。” <a class="header-anchor" href="#只要他们自己始终保持兴奋与期待-这种氛围自然就会在周围蔓延开来。我想-这样的氛围很能吸引人。" aria-label="Permalink to &quot;“只要他们自己始终保持兴奋与期待，这种氛围自然就会在周围蔓延开来。我想，这样的氛围很能吸引人。”&quot;">​</a></h3><p><strong>2023年春，BMSG旗下的2个男子组合迎来了重要进展：4月26日，BE:FIRST发行第三张单曲《Smile Again》；5月17日，继BE:FIRST之后推出的新组合MAZZEL正式出道。《Smile Again》是BE:FIRST的首支情歌，还拿下了大型商业合作，成为资生堂旗下ANESSA的全球宣传活动主题曲。这首歌在5月3日公布的Billboard JAPAN下载歌曲榜“Download Songs”上首次上榜便位居第1，却也成为BE:FIRST首支未能登顶Billboard JAPAN综合歌曲榜“JAPAN Hot 100”的歌曲。挡在它前面的是YOASOBI的《偶像》（原名《アイドル》）。这首现象级热门歌曲自4月12日上线以来，截至5月20日，已连续5周稳居“JAPAN Hot 100”榜首，并创下Billboard JAPAN史上播放量最快突破1亿次的纪录。</strong></p><p>BE:FIRST出道以来，在1年半里，先后凭《Gifted.》《Bye-Good-Bye》《Scream》《Boom Boom Back》4首歌曲登上了“JAPAN Hot 100”榜首，这次当然也想拿第一。不过，《偶像》实在太厉害了。按2023年“JAPAN Hot 100”年度榜单的综合积分来看，第1、第2名都是《偶像》，第3名是《Smile Again》（截至采访时）。BE:FIRST这次的成绩超过了此前大受欢迎的《Bye-Good-Bye》，我也因此真切感受到了这次发行的成效。</p><h3 id="mazzel展现出超乎预期的成长曲线" tabindex="-1">MAZZEL展现出超乎预期的成长曲线 <a class="header-anchor" href="#mazzel展现出超乎预期的成长曲线" aria-label="Permalink to &quot;MAZZEL展现出超乎预期的成长曲线&quot;">​</a></h3><p><strong>另一方面，MAZZEL于5月17日发行的出道单曲《Vivid》，在Billboard JAPAN综合歌曲榜“JAPAN Hot 100”上位列第4，并在CD销量和广播播放两项指标中均排名第1。这首歌不仅入选多家电台的月度重点推荐曲目，发行后，听众点播带来的播放次数也进一步增加。MV（音乐视频）评论区里，也不时能看到有人表示，自己是听了广播才来观看的。选秀节目《THE FIRST》曾在地面电视频道播出，引发广泛关注，BE:FIRST也顺着这股势头出道。相比之下，MAZZEL的起步虽没有那么引人注目，却已显露出凭借录音作品逐步打开知名度的势头。在以往的采访中，SKY-HI曾多次强调，“BE:FIRST和MAZZEL会采取不同的方式”。那么，他如何看待MAZZEL目前的开局呢？</strong></p><p>一句话来说，状态非常好。我们与环球音乐通过联合厂牌BE-U展开合作，当然也设定了数据和影响力方面的目标。目前这些目标大体都已达成，这是件好事。不过，比起这些，更重要的是，现在MAZZEL成员聚在一起时，氛围特别好。再看他们未来的成长空间和成长速度，我也对他们充满期待。</p><p>我再次感受到，果然“关系融洽的组合更容易成长”。看MAZZEL在音乐节目上的表演，每次都能看到明显的进步。可惜，现实中并不是练得越多，就一定进步得越多。现在的MAZZEL当然没有出道前那么充裕的练习时间，但他们已经开始意识到，自己如今要出现在镜头里、面对观众的目光。即使考虑到这种身份转变带来的自觉，他们这么早就展现出如此快的成长速度，我还是很惊讶。我想，这也是他们目前最可贵的地方。</p><p>另外，只要他们自己始终保持兴奋与期待，整个组合自然就会在周围营造出同样的氛围。我觉得，这样的氛围很能吸引人，所以他们今后也应该继续用心培养。至少现在，他们已经拥有这样的氛围，这就是非常好的事情。</p><p>BE:FIRST诞生于BMSG成立后的第一个大型项目。如今，公司的状况与BE:FIRST出道时不同，组合出道时需要达到的数据目标，确实也不一样。BE:FIRST出道那会儿，公司真的是每天都面临生死考验，稍有闪失就可能倒闭。我想，其他经纪公司大概也一样。有了第一个组合，第二个组合可以尝试的事情自然就会更多。对MAZZEL来说，正因为有BE:FIRST在先，他们才有更大的空间去迎接新的挑战。</p>',12)])])}const T=e(n,[["render",r]]);export{_ as __pageData,T as default};
